import type { Attribute, Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  tableBodyClassName,
  tableCaptionClassName,
  tableCellClassName,
  tableClassName,
  tableContainerClassName,
  tableFooterClassName,
  tableHeadClassName,
  tableHeaderClassName,
  tableRowClassName,
} from "./view";

export {
  tableBodyClassName,
  tableCaptionClassName,
  tableCellClassName,
  tableClassName,
  tableContainerClassName,
  tableFooterClassName,
  tableHeadClassName,
  tableHeaderClassName,
  tableRowClassName,
} from "./view";

type ViewConfig<ParentMessage> = Readonly<{
  children: readonly (Html | string)[];
  className?: string;
  attributes?: readonly Attribute<ParentMessage>[];
}>;

type CellViewConfig<ParentMessage> = ViewConfig<ParentMessage> &
  Readonly<{
    align?: "left" | "right";
  }>;

export type Invoice = Readonly<{
  invoice: string;
  status: string;
  method: string;
  amount: string;
}>;

export const invoices: readonly Invoice[] = [
  {
    invoice: "INV001",
    status: "Paid",
    method: "Credit Card",
    amount: "$250.00",
  },
  { invoice: "INV002", status: "Pending", method: "PayPal", amount: "$150.00" },
  {
    invoice: "INV003",
    status: "Unpaid",
    method: "Bank Transfer",
    amount: "$350.00",
  },
  {
    invoice: "INV004",
    status: "Paid",
    method: "Credit Card",
    amount: "$450.00",
  },
  { invoice: "INV005", status: "Paid", method: "PayPal", amount: "$550.00" },
  {
    invoice: "INV006",
    status: "Pending",
    method: "Bank Transfer",
    amount: "$200.00",
  },
  {
    invoice: "INV007",
    status: "Unpaid",
    method: "Credit Card",
    amount: "$300.00",
  },
];

const classNames = (...values: readonly (string | undefined)[]): string =>
  values
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

const textAlignClassName = (align: "left" | "right" | undefined): string =>
  align === "right" ? "text-right" : "text-left";

export const rootView = <ParentMessage>({
  children,
  className,
  attributes = [],
}: ViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.DataAttribute("slot", "table-container"),
      h.Class(classNames(tableContainerClassName, className)),
      ...attributes,
    ],
    [
      h.table(
        [h.DataAttribute("slot", "table"), h.Class(tableClassName)],
        children
      ),
    ]
  );
};

export const headerView = <ParentMessage>({
  children,
  className,
  attributes = [],
}: ViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.thead(
    [
      h.DataAttribute("slot", "table-header"),
      h.Class(classNames(tableHeaderClassName, className)),
      ...attributes,
    ],
    children
  );
};

export const bodyView = <ParentMessage>({
  children,
  className,
  attributes = [],
}: ViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.tbody(
    [
      h.DataAttribute("slot", "table-body"),
      h.Class(classNames(tableBodyClassName, className)),
      ...attributes,
    ],
    children
  );
};

export const footerView = <ParentMessage>({
  children,
  className,
  attributes = [],
}: ViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.tfoot(
    [
      h.DataAttribute("slot", "table-footer"),
      h.Class(classNames(tableFooterClassName, className)),
      ...attributes,
    ],
    children
  );
};

export const rowView = <ParentMessage>({
  children,
  className,
  attributes = [],
}: ViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.tr(
    [
      h.DataAttribute("slot", "table-row"),
      h.Class(classNames(tableRowClassName, className)),
      ...attributes,
    ],
    children
  );
};

export const headView = <ParentMessage>({
  children,
  className,
  align,
  attributes = [],
}: CellViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.th(
    [
      h.DataAttribute("slot", "table-head"),
      h.Class(
        classNames(tableHeadClassName, textAlignClassName(align), className)
      ),
      ...attributes,
    ],
    children
  );
};

export const cellView = <ParentMessage>({
  children,
  className,
  align,
  attributes = [],
}: CellViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.td(
    [
      h.DataAttribute("slot", "table-cell"),
      h.Class(
        classNames(tableCellClassName, textAlignClassName(align), className)
      ),
      ...attributes,
    ],
    children
  );
};

export const captionView = <ParentMessage>(
  children: readonly (Html | string)[],
  className?: string
): Html => {
  const h = html<ParentMessage>();

  return h.caption(
    [
      h.DataAttribute("slot", "table-caption"),
      h.Class(classNames(tableCaptionClassName, className)),
    ],
    children
  );
};

export const invoicesTableView = <ParentMessage>(): Html =>
  (() => {
    const h = html<ParentMessage>();

    return rootView<ParentMessage>({
      children: [
        captionView<ParentMessage>(["A list of your recent invoices."]),
        headerView<ParentMessage>({
          children: [
            rowView<ParentMessage>({
              children: [
                headView<ParentMessage>({
                  className: "w-[100px]",
                  children: ["Invoice"],
                }),
                headView<ParentMessage>({ children: ["Status"] }),
                headView<ParentMessage>({ children: ["Method"] }),
                headView<ParentMessage>({
                  align: "right",
                  children: ["Amount"],
                }),
              ],
            }),
          ],
        }),
        bodyView<ParentMessage>({
          children: invoices.map((invoice) =>
            rowView<ParentMessage>({
              children: [
                cellView<ParentMessage>({
                  className: "font-medium",
                  children: [invoice.invoice],
                }),
                cellView<ParentMessage>({ children: [invoice.status] }),
                cellView<ParentMessage>({ children: [invoice.method] }),
                cellView<ParentMessage>({
                  align: "right",
                  children: [invoice.amount],
                }),
              ],
            })
          ),
        }),
        footerView<ParentMessage>({
          children: [
            rowView<ParentMessage>({
              children: [
                cellView<ParentMessage>({
                  className: "font-medium",
                  children: ["Total"],
                }),
                cellView<ParentMessage>({
                  align: "right",
                  attributes: [h.Colspan(3)],
                  children: ["$2,500.00"],
                }),
              ],
            }),
          ],
        }),
      ],
    });
  })();

export const view = invoicesTableView;

export const tableContainerClassName = "relative w-full overflow-x-auto";

export const tableClassName = "w-full caption-bottom text-sm";

export const tableHeaderClassName = "[&_tr]:border-b";

export const tableBodyClassName = "[&_tr:last-child]:border-0";

export const tableFooterClassName =
  "border-t bg-gray-50/50 font-medium [&>tr]:last:border-b-0";

export const tableRowClassName =
  "border-b border-gray-200 transition-colors hover:bg-gray-50 data-[state=selected]:bg-gray-50";

export const tableHeadClassName =
  "h-10 px-2 text-left align-middle font-medium whitespace-nowrap text-gray-500";

export const tableCellClassName = "p-2 align-middle whitespace-nowrap";

export const tableCaptionClassName = "mt-4 text-sm text-gray-500";

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { describe, test } from "vitest";

import * as Table from "./index";

const view = (): Html => Table.invoicesTableView<never>();

describe("Table registry view", () => {
  test("renders the shadcn invoice table anatomy", () => {
    Scene.scene(
      {
        update: (model: undefined): readonly [undefined, []] => [model, []],
        view,
      },
      Scene.with(undefined),
      Scene.expect(Scene.text("A list of your recent invoices.")).toHaveAttr(
        "data-slot",
        "table-caption"
      ),
      Scene.expect(Scene.text("Invoice")).toHaveAttr("data-slot", "table-head"),
      Scene.expect(Scene.text("INV001")).toHaveAttr("data-slot", "table-cell"),
      Scene.expect(Scene.text("$2,500.00")).toHaveAttr(
        "data-slot",
        "table-cell"
      )
    );
  });
});
